parameters.jsCode:
const data = $json.sales_data || [];

const startDate = $json.report_period?.start || "";
const endDate = $json.report_period?.end || "";

let totalOrders = data.length;
let completedOrders = 0;
let cancelledOrders = 0;
let returnedOrders = 0;

let totalQuantity = 0;
let grossSales = 0;
let totalDiscounts = 0;
let netSales = 0;
let realizedSales = 0;

const categories = {};
const cities = {};
const products = {};

for (const row of data) {

  const quantity = Number(row.Quantity) || 0;
  const price = Number(row.Unit_Price_INR) || 0;
  const discount = Number(row.Discount_INR) || 0;

  const gross = quantity * price;
  const net = gross - discount;

  totalQuantity += quantity;
  grossSales += gross;
  totalDiscounts += discount;
  netSales += net;

  const status = String(row.Status || "").toLowerCase();

  if (status === "completed") {
    completedOrders++;
    realizedSales += net;
  }

  if (status === "cancelled") {
    cancelledOrders++;
  }

  if (status === "returned") {
    returnedOrders++;
  }

  const category = row.Category || "Unknown";

  if (!categories[category]) {
    categories[category] = {
      orders: 0,
      quantity: 0,
      net_sales: 0
    };
  }

  categories[category].orders++;
  categories[category].quantity += quantity;
  categories[category].net_sales += net;


  const city = row.City || "Unknown";

  if (!cities[city]) {
    cities[city] = {
      orders: 0,
      net_sales: 0
    };
  }

  cities[city].orders++;
  cities[city].net_sales += net;


  const product = row.Product || "Unknown";

  if (!products[product]) {
    products[product] = {
      quantity: 0,
      net_sales: 0
    };
  }

  products[product].quantity += quantity;
  products[product].net_sales += net;
}

const completionRate =
  totalOrders ? (completedOrders / totalOrders) * 100 : 0;

const cancellationRate =
  totalOrders ? (cancelledOrders / totalOrders) * 100 : 0;

const returnRate =
  totalOrders ? (returnedOrders / totalOrders) * 100 : 0;

const averageOrderValue =
  completedOrders ? realizedSales / completedOrders : 0;

const averageSellingPrice =
  totalQuantity ? realizedSales / totalQuantity : 0;

const categoryList = Object.entries(categories)
  .map(([category, value]) => ({
    category,
    orders: value.orders,
    quantity: value.quantity,
    net_sales: value.net_sales
  }))
  .sort((a, b) => b.net_sales - a.net_sales);

const cityList = Object.entries(cities)
  .map(([city, value]) => ({
    city,
    orders: value.orders,
    net_sales: value.net_sales
  }))
  .sort((a, b) => b.net_sales - a.net_sales);

const productList = Object.entries(products)
  .map(([product, value]) => ({
    product,
    quantity_sold: value.quantity,
    net_sales: value.net_sales
  }))
  .sort((a, b) => b.net_sales - a.net_sales);

return [{
  json: {
    period: {
      start_date: startDate,
      end_date: endDate
    },

    overall_metrics: {
      total_orders: totalOrders,
      completed_orders: completedOrders,
      cancelled_orders: cancelledOrders,
      returned_orders: returnedOrders,
      total_quantity: totalQuantity,
      gross_sales: grossSales,
      total_discounts: totalDiscounts,
      net_sales: netSales,
      realized_sales: realizedSales,
      average_order_value: averageOrderValue,
      average_selling_price: averageSellingPrice
    },

    status_metrics: {
      completion_rate: completionRate,
      cancellation_rate: cancellationRate,
      return_rate: returnRate
    },

    sales_by_category: categoryList,

    sales_by_city: cityList,

    top_products: productList.slice(0, 5),

    lowest_products: productList.slice(-5).reverse(),

    data_quality_notes: [
      "Metrics calculated directly from the provided sales dataset."
    ]
  }
}];

const rows = $input.all().map(item => item.json);

const now = new Date();

// Last 7 days including today
const startDate = new Date(now);
startDate.setDate(startDate.getDate() - 6);
startDate.setHours(0, 0, 0, 0);

const endDate = new Date(now);
endDate.setHours(23, 59, 59, 999);

const weeklyRows = rows.filter(row => {
  if (!row.Order_Date) return false;

  const orderDate = new Date(row.Order_Date);

  return orderDate >= startDate && orderDate <= endDate;
});

return [
  {
    json: {
      report_period: {
        start: startDate.toISOString().split('T')[0],
        end: endDate.toISOString().split('T')[0]
      },

      generated_at: now.toISOString(),

      total_rows: weeklyRows.length,

      sales_data: weeklyRows
    }
  }
];
